import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function isEmpty(v: unknown): boolean {
  return v === undefined || v === null || (typeof v === 'string' && v.trim() === '');
}

function toInt(v: unknown, label: string): number {
  const text = String(v).trim();
  if (!/^-?\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바른 숫자가 아닙니다.');
  }
  return Number(text);
}

@Controller('api/v1')
export class FnSfr03101Controller {
  @Get('/document-categories')
  async listDocumentCategories(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const query = checks.queryOf(req.query);
    const page = isEmpty(query['page']) ? 0 : toInt(query['page'], '페이지');
    let size = isEmpty(query['size']) ? DEFAULT_SIZE : toInt(query['size'], '크기');
    if (page < 0 || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 또는 크기 값이 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const departmentId = isEmpty(query['managingDepartmentId'])
      ? null
      : toInt(query['managingDepartmentId'], '관리부서');
    return transaction(async (db) => {
      const where = '(CAST(:departmentId AS bigint) IS NULL OR managing_department_id = CAST(:departmentId AS bigint))';
      const items = await db.query(
        'SELECT document_category_id AS "documentCategoryId", category_name AS "categoryName", category_code AS "categoryCode", managing_department_id AS "managingDepartmentId" '
          + 'FROM document_category WHERE ' + where
          + ' ORDER BY document_category_id DESC LIMIT :size OFFSET :offset',
        { departmentId, size, offset: page * size },
      );
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" FROM document_category WHERE ' + where,
        { departmentId },
      );
      const total = Number(counted[0]?.total ?? 0);
      return { items, page, size, total };
    });
  }

  @Post('/document-categories')
  @HttpCode(200)
  async createDocumentCategory(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const data = checks.inputOf(req.body);
    if (isEmpty(data['managingDepartmentId'])) {
      throw new ApiError(422, 'REQUIRED_FIELD_MISSING', '관리부서를 선택해 주세요.');
    }
    if (isEmpty(data['categoryName'])) {
      throw new ApiError(422, 'REQUIRED_FIELD_MISSING', '문서분류/단위업무명을 입력해 주세요.');
    }
    const departmentId = toInt(data['managingDepartmentId'], '관리부서');
    if (typeof data['categoryName'] !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서분류/단위업무명 형식이 올바르지 않습니다.');
    }
    const categoryName = data['categoryName'].trim();
    if (categoryName.length > 200) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서분류/단위업무명은 200자 이하여야 합니다.');
    }
    let categoryCode: string | null = null;
    if (!isEmpty(data['categoryCode'])) {
      if (typeof data['categoryCode'] !== 'string' || data['categoryCode'].trim().length > 50) {
        throw new ApiError(400, 'VALIDATION_FAILED', '분류 코드는 50자 이하 글자여야 합니다.');
      }
      categoryCode = data['categoryCode'].trim();
    }
    return transaction(async (db) => {
      const dept = await db.query(
        'SELECT department_id FROM department WHERE department_id = CAST(:departmentId AS bigint)',
        { departmentId },
      );
      if (dept.length === 0) {
        throw new ApiError(404, 'DEPARTMENT_NOT_FOUND', '관리부서가 존재하지 않습니다.');
      }
      const rows = await db.query(
        'INSERT INTO document_category (managing_department_id, category_name, category_code, created_at, updated_at) '
          + 'VALUES (CAST(:departmentId AS bigint), :categoryName, :categoryCode, now(), now()) '
          + 'RETURNING document_category_id AS "documentCategoryId"',
        { departmentId, categoryName, categoryCode },
      );
      return { documentCategoryId: Number(rows[0].documentCategoryId) };
    });
  }
}

