import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  LookupSelect,
  RefName,
  ErrorText,
  Tiles,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const PAGE_SIZE = 20;

export default function FnSfr03101Page({ role, notify }: PageProps) {
  const [deptInput, setDeptInput] = useState<number | string>('');
  const [dept, setDept] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [formDept, setFormDept] = useState<number | string>('');
  const [name, setName] = useState('');
  const [code, setCode] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/document-categories', role, undefined, {
      managingDepartmentId: dept,
      page,
      size: PAGE_SIZE,
    }),
    [role, dept, page],
  );

  const rules = useData<Page>(
    () => call<Page>('GET', '/numbering-rules', role, undefined, { size: 5 }),
    [role],
  );

  const rows: Row[] = list.data?.items ?? [];
  const total = list.data?.total ?? 0;

  function openCreate() {
    setFormDept('');
    setName('');
    setCode('');
    setCreating(true);
  }

  async function submit() {
    if (formDept === '' || formDept === undefined) {
      throw new Error('관리부서를 선택해 주세요.');
    }
    if (name.trim() === '') {
      throw new Error('문서분류/단위업무명을 입력해 주세요.');
    }
    await call('POST', '/document-categories', role, {
      managingDepartmentId: formDept,
      categoryName: name.trim(),
      categoryCode: code.trim(),
    });
    notify('문서분류를 등록했습니다.');
    setCreating(false);
    setPage(0);
    list.reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>문서분류 현황</h2>
        <Tiles items={[['조회된 문서분류', <Num value={total} />]]} />
      </section>

      <section className="box span-8">
        <h2>문서분류</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setDept(deptInput);
          }}
          onReset={() => {
            setPage(0);
            setDeptInput('');
            setDept('');
          }}
        >
          <Field label="관리부서">
            <LookupSelect table="department" role={role} value={deptInput} onChange={setDeptInput} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={openCreate}>문서분류 등록</button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          columns={[
            { key: 'documentCategoryId', label: '문서분류 ID' },
            { key: 'categoryName', label: '문서분류/단위업무명' },
            { key: 'categoryCode', label: '분류 코드' },
            {
              key: 'managingDepartmentId',
              label: '관리부서',
              render: (row) => <RefName table="department" role={role} value={row.managingDepartmentId} />,
            },
          ]}
          rows={rows}
          empty="등록된 문서분류가 없습니다."
        />
        <Pager page={page} size={PAGE_SIZE} total={total} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>채번 규칙</h2>
        {rules.error ? <ErrorText text={rules.error} /> : null}
        <DataTable
          columns={[
            { key: 'targetType', label: '대상 유형' },
            { key: 'resetUnit', label: '채번 단위' },
            { key: 'prefix', label: '접두어' },
            { key: 'digits', label: '자릿수', render: (row) => <Num value={row.digits} /> },
          ]}
          rows={rules.data?.items ?? []}
          empty="등록된 채번 규칙이 없습니다."
        />
      </section>

      {creating ? (
        <Drawer title="문서분류 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={submit} submit="등록">
            <Field label="관리부서" required>
              <LookupSelect table="department" role={role} value={formDept} onChange={setFormDept} />
            </Field>
            <Field label="문서분류/단위업무명" required>
              <TextInput value={name} onChange={setName} />
            </Field>
            <Field label="분류 코드">
              <TextInput value={code} onChange={setCode} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
